questions.solution:
function specificity(pattern: string): string {
  return pattern
    .split("/")
    .filter((segment) => segment.length > 0)
    .map((segment) => (segment.startsWith(":") ? "2" : segment.startsWith("*") ? "1" : "3"))
    .join("");
}

const routes = ["/tasks/*rest", "/tasks/:id", "/tasks/stats", "/tasks/:id/notes"];
const sorted = [...routes].sort((a, b) => {
  const x = specificity(a);
  const y = specificity(b);
  return x === y ? 0 : x > y ? -1 : 1;
});
console.log(sorted);

