function hasDotSegment(target: string): boolean {
  const path = target.split("?")[0] ?? "";
  for (const segment of path.split(/[\/\\]/)) {
    let decoded: string;
    try {
      decoded = decodeURIComponent(segment);
    } catch {
      return true;
    }
    if (decoded === "." || decoded === "..") return true;
  }
  return false;
}

