const table: [pattern: string, regex: RegExp][] = [
  ["/orders/latest", /^\/orders\/latest$/],
  ["/orders/:ref", /^\/orders\/[^/]+$/],
  ["/orders/:id(\\d+)", /^\/orders\/\d+$/],
];

function match(path: string): string | undefined {
  return table.find(([, regex]) => regex.test(path))?.[0];
}

function deadRoutes(samples: [pattern: string, sample: string][]): string[] {
  return samples.filter(([pattern, sample]) => match(sample) !== pattern).map(([pattern]) => pattern);
}

console.log(
  deadRoutes([
    ["/orders/latest", "/orders/latest"],
    ["/orders/:ref", "/orders/INV-7"],
    ["/orders/:id(\\d+)", "/orders/17"],
  ]),
);
